package com.aoo.bcg.poker.cx;

import com.aoo.bcg.gamespi.*;
import com.aoo.bcg.gamespi.CarryBillingEffectSource.*;
import com.aoo.bcg.gamespi.time.OperationDeadline;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

final class CxCarryBillingEffectsTest {
    private CxSession waiting(){return new CxSession(9001,101,7,CxRules.from(Map.of("startPlayers",4,"roundCount",10)));}
    private GameCommandRequest request(String action,String op,long actor,int seat,long amount){return new GameCommandRequest("poker.chengdu2999."+action+"_req",op,1,9001,0,CxRules.VERSION,Long.toString(actor),seat,Map.of("carryScore",amount));}
    private int seat(CxSession s,long actor){return ((Number)s.viewFor(actor).get("viewerSeat")).intValue();}
    private long count(CxSession s,String op,Stage stage){return s.pendingCarryEffects().effects().stream().filter(e->e.originalRequestId().equals(op)&&e.stage()==stage).count();}
    private CxSession active(){var s=new CxSession(9001,101,7,CxRules.from(Map.of()));s.sit(101L,100,"first");s.sit(102L,100,"second");return s;}
    private CxSession terminal(){var s=active();var state=new LinkedHashMap<>(s.authoritativeState());state.put("phase","FINISHED");state.put("terminalDeadlineEpochMillis",System.currentTimeMillis()+60000);state.put("operationDeadline",OperationDeadline.none().toMap());return CxSession.restore(state);}
    @Test void pureProposalDoesNotAllocateOrApplyAndRequestedResolvesSeat(){var s=waiting();var before=s.authoritativeState();var r=request("sit","initial",101,-1,100);var p=s.proposeCarry(r).orElseThrow();assertEquals(-1,p.seatId());assertEquals(Kind.INITIAL,p.kind());assertEquals(before,s.authoritativeState());s.execute(r);assertEquals(1,count(s,"initial",Stage.REQUESTED));assertEquals(1,count(s,"initial",Stage.APPLIED));assertEquals(0,count(s,"initial",Stage.USED));assertTrue(s.pendingCarryEffects().effects().stream().allMatch(e->e.seatId()==seat(s,101)&&e.seatId()>=0));assertFalse(s.viewFor(101).containsKey("carryBilling"));}
    @Test void rejectedOrDuplicateRequestsProduceNoEffects(){var s=waiting();var before=s.authoritativeState();assertThrows(IllegalArgumentException.class,()->s.proposeCarry(request("sit","bad",101,-1,-1)));assertEquals(before,s.authoritativeState());s.execute(request("sit","accepted",101,-1,100));var after=s.authoritativeState();assertThrows(IllegalStateException.class,()->s.execute(request("sit","accepted",101,-1,100)));assertEquals(after,s.authoritativeState());assertTrue(s.proposeCarry(request("state","query",101,-1,0)).isEmpty());}
    @Test void zeroReservationConfirmationTerminatesUnusedAndAppliesExactAmount(){var s=waiting();s.sit(101L,0,"reserved");int seat=seat(s,101);var r=request("sit","confirmed",101,-1,321);assertEquals(Kind.CONFIRM,s.proposeCarry(r).orElseThrow().kind());s.execute(r);assertEquals(1,count(s,"reserved",Stage.TERMINATED_UNUSED));assertEquals(1,count(s,"confirmed",Stage.APPLIED));assertEquals(0,count(s,"confirmed",Stage.USED));assertEquals(321L,((Map<?,?>)s.authoritativeState().get("scores")).get(seat));}
    @Test void actualOpeningCommitUsesEachAttemptOnceAndNeverTerminatesUsed(){var s=active();assertEquals(1,count(s,"first",Stage.USED));assertEquals(1,count(s,"second",Stage.USED));assertEquals(0,count(s,"first",Stage.TERMINATED_UNUSED));var restored=CxSession.restore(s.authoritativeState());assertEquals(s.authoritativeState(),restored.authoritativeState());assertEquals(s.pendingCarryEffects(),restored.pendingCarryEffects());}
    @Test void restartPendingRestoresOriginalRequestUntilAnotherRequestTriggersApplication(){var s=terminal();int a=seat(s,101),b=seat(s,102);s.execute(request("restart","restart-A",101,a,200));assertEquals(1,count(s,"restart-A",Stage.REQUESTED));assertEquals(0,count(s,"restart-A",Stage.APPLIED));var restored=CxSession.restore(s.authoritativeState());assertEquals(s.authoritativeState(),restored.authoritativeState());restored.execute(request("restart","restart-B",102,b,300));assertEquals(1,count(restored,"restart-A",Stage.APPLIED));assertEquals(1,count(restored,"restart-A",Stage.USED));assertEquals(0,count(restored,"restart-A",Stage.TERMINATED_UNUSED));assertEquals(1,count(restored,"restart-B",Stage.USED));assertTrue(restored.pendingCarryEffects().effects().stream().filter(e->e.originalRequestId().equals("restart-A")).allMatch(e->e.actorId()==101&&e.seatId()==a));}
    @Test void supersedingPendingRestartTerminatesOnlyOldAttempt(){var s=terminal();int a=seat(s,101);s.execute(request("restart","pending-old",101,a,200));s.execute(request("restart","pending-new",101,a,400));assertEquals(1,count(s,"pending-old",Stage.TERMINATED_UNUSED));assertEquals(0,count(s,"pending-old",Stage.APPLIED));assertEquals(0,count(s,"pending-new",Stage.TERMINATED_UNUSED));assertEquals(0,count(s,"first",Stage.TERMINATED_UNUSED));}
    @Test void standingTerminatesUnappliedRestartWithoutUsingIt(){var s=terminal();int a=seat(s,101);s.execute(request("restart","pending",101,a,200));s.execute(request("stand","stand",101,a,0));assertEquals(1,count(s,"pending",Stage.TERMINATED_UNUSED));assertEquals(0,count(s,"pending",Stage.USED));assertEquals(0,count(s,"first",Stage.TERMINATED_UNUSED));}
    @Test void rebuyIsNotUsedByHistoricalPlayedSeatsButByNextOpeningCommit(){var s=active();int a=seat(s,101);var state=new LinkedHashMap<>(s.authoritativeState());state.put("phase","ROUND_SETTLEMENT");state.put("operationDeadline",OperationDeadline.none().toMap());state.put("seatRetentionDeadlineEpochMillis",Map.of(a,System.currentTimeMillis()+60000));var scores=new LinkedHashMap<Integer,Long>();((Map<?,?>)state.get("scores")).forEach((k,v)->scores.put(Integer.parseInt(k.toString()),((Number)v).longValue()));scores.put(a,0L);state.put("scores",scores);s=CxSession.restore(state);s.execute(request("rebuy","new-rebuy",101,a,500));assertEquals(1,count(s,"new-rebuy",Stage.APPLIED));assertEquals(0,count(s,"new-rebuy",Stage.USED));assertEquals(500L,((Map<?,?>)s.authoritativeState().get("scores")).get(a));state=new LinkedHashMap<>(s.authoritativeState());int trigger=((Number)state.get("roundSettlementTriggerSeat")).intValue();state.put("roundSettlementDeadlineEpochMillis",1L);s=CxSession.restore(state);long actor=((Number)((Map<?,?>)s.authoritativeState().get("players")).get(trigger)).longValue();s.execute(request("timeout","automatic-next",actor,trigger,0));assertEquals(1,count(s,"new-rebuy",Stage.USED));assertEquals(0,count(s,"automatic-next",Stage.REQUESTED));}
    @Test void exactPrefixAckIsStableRestorableAndDoesNotChangeGameplayVersion(){var s=waiting();s.sit(101L,100,"one");var batch=s.pendingCarryEffects();assertEquals(batch,s.pendingCarryEffects());var before=new LinkedHashMap<>(s.authoritativeState());assertThrows(IllegalArgumentException.class,()->s.acknowledgeCarryEffects(batch.throughOrdinal(),"wrong"));assertEquals(before,s.authoritativeState());s.acknowledgeCarryEffects(batch.throughOrdinal(),batch.hash());var after=new LinkedHashMap<>(s.authoritativeState());var metadata=after.remove("carryBilling");before.remove("carryBilling");assertEquals(before,after);assertTrue(s.pendingCarryEffects().effects().isEmpty());s.acknowledgeCarryEffects(batch.throughOrdinal(),batch.hash());assertEquals(metadata,s.authoritativeState().get("carryBilling"));var restored=CxSession.restore(s.authoritativeState());assertEquals(s.authoritativeState(),restored.authoritativeState());}
    @Test void partialPrefixAckRetainsLaterEffectsAndLegacySnapshotDoesNotInventProof(){var s=waiting();s.sit(101L,100,"one");var batch=s.pendingCarryEffects();var first=batch.effects().getFirst();var prefix=new Batch(9001,first.ordinal(),List.of(first));s.acknowledgeCarryEffects(prefix.throughOrdinal(),prefix.hash());assertEquals(1,s.pendingCarryEffects().effects().size());assertEquals(s.authoritativeState(),CxSession.restore(s.authoritativeState()).authoritativeState());var legacy=new LinkedHashMap<>(s.authoritativeState());legacy.remove("carryBilling");var restored=CxSession.restore(legacy);assertTrue(restored.pendingCarryEffects().effects().isEmpty());assertEquals(0,restored.pendingCarryEffects().throughOrdinal());}
    @Test void emptyBatchAckIsAnIdempotentNoOpBeforeAndAfterRealEffects(){var s=waiting();var empty=s.pendingCarryEffects();var before=s.authoritativeState();s.acknowledgeCarryEffects(empty.throughOrdinal(),empty.hash());assertEquals(before,s.authoritativeState());s.sit(101L,100,"one");var batch=s.pendingCarryEffects();s.acknowledgeCarryEffects(batch.throughOrdinal(),batch.hash());empty=s.pendingCarryEffects();before=s.authoritativeState();s.acknowledgeCarryEffects(empty.throughOrdinal(),empty.hash());assertEquals(before,s.authoritativeState());}
}
